import { normalizeKey } from './keys.mjs';
export function createCache() {
  const values = new Map();
  return {
    put(key, value) { values.set(key, value); },
    get(key) { return values.get(normalizeKey(key)); },
    invalidate(key) { return values.delete(key); }
  };
}

